#include "Stereo.h"
static void testStereo(const File& root,Assets& assets){
    StereoSettings settings;StereoUtility processor;processor.prepare(48000);processor.setSettings(settings);float l=.23456789f,r=-.9876543f;processor.process(l,r);expect(l==.23456789f&&r==-.9876543f,"bypassed stereo tools preserve samples exactly");settings.enabled=true;processor.setSettings(settings);processor.process(l,r);expect(l==.23456789f&&r==-.9876543f,"enabled neutral stereo matrix preserves samples exactly");
    for(int mask=0;mask<16;++mask)for(float width:{0.f,1.f,2.f})for(float trim:{-24.f,0.f,6.f}){
        StereoSettings s;s.enabled=true;s.mono=mask&1;s.swap=mask&2;s.invertLeft=mask&4;s.invertRight=mask&8;s.width=width;s.trim=trim;processor.prepare(44100);processor.setSettings(s);float left=.37f,right=-.18f;double a=s.invertLeft?-.37f:.37f,b=s.invertRight?.18f:-.18f;if(s.swap)std::swap(a,b);double mid=(a+b)*.5,side=(a-b)*.5*(s.mono?0:width),gain=std::pow(10.,trim/20.);processor.process(left,right);expect(std::abs(left-(mid+side)*gain)<.000001&&std::abs(right-(mid-side)*gain)<.000001,"stereo matrix matches polarity, swap, mid-side width, mono and trim algebra");
    }
    for(double rate:{8000.,44100.,48000.,96000.,192000.}){
        processor.prepare(rate);processor.setSettings({});settings={};settings.enabled=true;settings.invertLeft=true;processor.setSettings(settings);l=.5f;r=.25f;processor.process(l,r);expect(l>.49f&&l<.5f&&r==.25f,"live polarity changes start with a short smooth coefficient transition");bool finite=true;for(int i=1;i<(int)rate;++i){l=.5f;r=.25f;processor.process(l,r);finite&=std::isfinite(l)&&std::abs(l)<=.5f&&r==.25f;}expect(finite&&l==-.5f,"stereo transitions remain bounded and settle at the selected matrix across rates");settings.enabled=false;processor.setSettings(settings);for(int i=0;i<(int)rate;++i){l=.5f;r=.25f;processor.process(l,r);}expect(l==.5f&&r==.25f,"smoothed stereo bypass settles to exact dry samples");
        settings.enabled=true;settings.mono=true;processor.setSettings(settings);processor.reset();l=.5f;r=.25f;processor.process(l,r);expect(l==-.125f&&r==-.125f,"Stop/reset immediately aligns stereo processing to its current target");
    }
    auto project=emptyProject();project.masterSoftClip=true;project.loop=false;project.bpm=120;project.patterns[0].length=4;project.patterns[0].lanes[7]={{0,1,60,.8f}};auto baseline=render(project,assets,root,12000);Project loaded;
    for(int schema=1;schema<=11;++schema){auto old=projectToJson(project);old.getDynamicObject()->setProperty("schema",schema);for(auto& track:*old["tracks"].getArray())track["mixer"].getDynamicObject()->removeProperty("stereo");expect(projectFromJson(old,loaded).wasOk()&&loaded.tracks[7].mixer.stereo==StereoSettings{},"schemas 1 through 11 migrate to neutral bypassed stereo tools");auto output=render(loaded,assets,root,12000);bool same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<12000;++i)same&=output.getSample(ch,i)==baseline.getSample(ch,i);expect(same,"legacy stereo migration preserves every rendered audio sample exactly");}
    settings={};settings.enabled=true;settings.width=1.7f;settings.trim=-3;settings.swap=true;settings.invertRight=true;project.tracks[7].mixer.stereo=settings;
    auto file=root.getChildFile("stereo-project.pulse");expect(saveProject(project,file).wasOk()&&loadProject(file,loaded).wasOk()&&loaded.tracks[7].mixer.stereo==settings&&loaded.patterns[0].length==4,"schema 12 round-trips all stereo settings and variable pattern length");
    auto before=JSON::toString(projectToJson(loaded));auto missing=projectToJson(project);(*missing["tracks"].getArray())[7]["mixer"].getDynamicObject()->removeProperty("stereo");expect(projectFromJson(missing,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"schema 12 rejects missing stereo settings atomically");
    for(auto key:{"enabled","mono","swap","invertLeft","invertRight","width","trim"}){auto bad=stereoToJson(settings);bad.getDynamicObject()->setProperty(key,"invalid");auto value=settings;expect(stereoFromJson(bad,value).failed()&&value==settings,"stereo JSON rejects wrongly typed values without changing destination");bad=stereoToJson(settings);bad.getDynamicObject()->removeProperty(key);expect(stereoFromJson(bad,value).failed()&&value==settings,"stereo JSON requires every switch and numeric value");}
    for(float invalid:{-.001f,2.001f,std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity()}){auto bad=project;bad.tracks[7].mixer.stereo.width=invalid;auto hash=SHA256(file).toHexString();expect(saveProject(bad,file).failed()&&SHA256(file).toHexString()==hash,"invalid stereo values cannot replace a valid project");auto playback=std::make_unique<Playback>();String warning;expect(compilePlayback(bad,assets,root,*playback,warning).failed(),"invalid stereo values cannot reach audio snapshots");}
    for(double invalid:{-24.001,6.001,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){auto bad=stereoToJson(settings);bad.getDynamicObject()->setProperty("trim",invalid);auto value=settings;expect(stereoFromJson(bad,value).failed()&&value==settings,"stereo trim rejects overflow, nonfinite values and out-of-range doubles");}
    auto output=render(project,assets,root,24000,1),other=render(project,assets,root,24000,731);bool same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)same&=output.getSample(ch,i)==other.getSample(ch,i);expect(same,"stereo audio processing is independent of callback block size");
    auto monitor=emptyProject();monitor.tracks[0].mixer.stereo.enabled=true;monitor.tracks[0].mixer.stereo.mono=true;auto e=makeEngine(monitor,assets,root);e->playing.store(false);std::array<float,512> left,right,inputL,inputR;inputL.fill(.2f);inputR.fill(-.2f);for(int i=0;i<20;++i)e->render(left.data(),right.data(),512,{inputL.data(),inputR.data(),0,1});float peak=0;for(float sample:left)peak=jmax(peak,std::abs(sample));expect(peak==0,"post-chain mono cancels equal opposite-phase monitored inputs before Master");
    project.tracks[7].mixer.stereo={};project.tracks[7].mixer.output=5;project.tracks[5].isBus=true;project.tracks[5].pan=0;project.tracks[5].mixer.stereo.enabled=true;project.tracks[5].mixer.stereo.mono=true;project.tracks[7].pan=-.6f;project.tracks[7].send=0;output=render(project,assets,root,24000);same=true;for(int i=0;i<24000;++i)same&=output.getSample(0,i)==output.getSample(1,i);expect(same&&output.getMagnitude(0,0,24000)>.001,"bus stereo tools process the routed mix before Master");
    ProjectTemplate info;expect(saveProjectTemplate(project,root,root.getChildFile("stereo-templates"),"Stereo bus","Mono bus utility",TemplateContent::complete,info).wasOk()&&loadProjectTemplate(info,loaded).wasOk()&&loaded.tracks[5].mixer.stereo==project.tracks[5].mixer.stereo,"local templates retain source and bus stereo utility settings");
    auto chain=captureEffectChain("Six effects",project.tracks[5].mixer);expect(chain.settings.stereo==StereoSettings{}&&validateEffectChain(chain).wasOk(),"effect-chain capture excludes the separate post-chain stereo utility");
    RenderSettings rs;rs.format=RenderFormat::wav;rs.bits=32;rs.tailSeconds=0;std::atomic<bool> cancel{false};std::atomic<float> progress{0};auto exportFile=root.getChildFile("stereo-export.wav");auto result=renderAudio(project,assets,root,exportFile,rs,-1,&cancel,&progress);AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(exportFile));bool exported=result.wasOk()&&reader;AudioBuffer<float> decoded(2,24000);if(exported){reader->read(&decoded,0,24000,0,true,true);for(int i=0;i<24000;++i)exported&=decoded.getSample(0,i)==decoded.getSample(1,i);}expect(exported&&decoded.getMagnitude(0,0,24000)>.001,"offline float WAV export includes the routed stereo utility");
}
